import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]

def go(i, a, b):
    gain = g[i][a] + (g[i][b] if a != b else 0)
    if i == r - 1:
        return gain
    best = 0
    for da in (-1, 0, 1):
        for db in (-1, 0, 1):
            na, nb = a + da, b + db
            if 0 <= na < c and 0 <= nb < c:
                best = max(best, go(i + 1, na, nb))
    return gain + best

print(go(0, 0, c - 1))

